/**
 * Parser and types for the committed `frontend/public/table/shells.json`.
 *
 * The manifest is generated by `tools/render/bake_shells.py` and validated by
 * `tools/render/scripts/check-shells.mjs`. This module trusts the committed
 * values but rejects a structurally wrong or drifted document at startup,
 * because every draw position and glyph placement is derived from it.
 *
 * Coordinates are CSS px of the @1x texture with a top-left origin. The @2x
 * texture is exactly `pixelRatio` times the resolution, so the atlas can draw
 * at 2x without changing logical layout.
 */
import { SHELL_IDS, isShellId } from './tiles';
import type { ShellId } from './tiles';

/** `[x, y]` in @1x CSS px, texture top-left origin. */
export type PointPx = readonly [number, number];

/** A shell's visible face plate, in face-local corner order. */
export type FaceQuad = readonly [PointPx, PointPx, PointPx, PointPx];

export interface ShellPadding {
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly left: number;
}

export interface ShellPose {
  readonly rotateXDeg: number;
  readonly rotateYDeg: number;
  readonly rotateZDeg: number;
}

export interface ShellStats {
  readonly textureFile: string;
  readonly textureFile2x: string;
  readonly texWidth: number;
  readonly texHeight: number;
  readonly anchorX: number;
  readonly anchorY: number;
  readonly advanceWidth: number;
  readonly advanceHeight: number;
  readonly padding: ShellPadding;
  /**
   * Screen-space rotation of the tile face: 0 for upright shells, 90 for
   * `shell_flat_sideways` (a 90° counter-clockwise glyph rotation).
   */
  readonly faceRotationDeg: 0 | 90;
  readonly faceQuad: FaceQuad;
  readonly faceQuadOrder: string;
  /** Projected tile axis steps in @1x px; use these for tight grids. */
  readonly gridStepPx: { readonly x: PointPx; readonly y: PointPx };
  readonly projection: string;
  readonly pose: ShellPose;
}

export interface ShellsManifest {
  readonly version: number;
  readonly generatedBy: string;
  readonly pixelRatio: number;
  readonly shells: Readonly<Record<ShellId, ShellStats>>;
}

function fail(message: string): never {
  throw new Error(`shells.json: ${message}`);
}

function finite(value: unknown, field: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) fail(`${field} must be a finite number`);
  return value;
}

function point(value: unknown, field: string): PointPx {
  if (
    !Array.isArray(value) ||
    value.length !== 2 ||
    value.some((entry) => typeof entry !== 'number' || !Number.isFinite(entry))
  ) {
    fail(`${field} must be [x, y]`);
  }
  return [value[0], value[1]] as const;
}

function positive(value: unknown, field: string): number {
  const number = finite(value, field);
  if (number <= 0) fail(`${field} must be positive`);
  return number;
}

function nonNegative(value: unknown, field: string): number {
  const number = finite(value, field);
  if (number < 0) fail(`${field} must be zero or positive`);
  return number;
}

function parseRotation(value: unknown, field: string): 0 | 90 {
  if (value !== 0 && value !== 90) fail(`${field} must be 0 or 90`);
  return value;
}

function parseQuad(value: unknown, field: string): FaceQuad {
  if (!Array.isArray(value) || value.length !== 4) fail(`${field} must have four corners`);
  const corners = value.map((corner, index) => point(corner, `${field}[${index}]`));
  return [corners[0], corners[1], corners[2], corners[3]];
}

/** True when a shell shows its blue resin back, so no glyph belongs on it. */
export function isFaceDownShell(shell: ShellStats): boolean {
  // The three wall shells are the face-down poses: the tile is flipped 180°
  // about X, and the visible plate is local z = 0. The face-up shells are the
  // three with no 180° flip.
  return Math.abs(shell.pose.rotateXDeg % 360) === 180;
}

/**
 * Screen rotation, in degrees counter-clockwise, that maps the glyph's own
 * top-left-to-top-right edge onto the faceQuad's first edge. 0 for upright
 * shells, 90 for the sideways shell. This is what `faceRotationDeg` publishes;
 * recomputing it from the quad catches a manifest whose corner order drifted.
 */
export function screenRotationOfQuad(quad: FaceQuad): 0 | 90 | 270 {
  const [topLeft, topRight] = quad;
  const dx = topRight[0] - topLeft[0];
  const dy = topRight[1] - topLeft[1];
  if (Math.abs(dx) >= Math.abs(dy)) return 0;
  // Screen y grows downward. A top edge pointing up (dy < 0) is a 90° CCW
  // rotation of the glyph; pointing down is 90° clockwise, which no committed
  // shell uses.
  return dy < 0 ? 90 : 270;
}

function parseShell(id: ShellId, raw: unknown): ShellStats {
  if (typeof raw !== 'object' || raw === null) fail(`${id} must be an object`);
  const shell = raw as Record<string, unknown>;
  const textureFile = shell.textureFile;
  const textureFile2x = shell.textureFile2x;
  if (typeof textureFile !== 'string' || !textureFile) fail(`${id}.textureFile must be a path`);
  if (typeof textureFile2x !== 'string' || !textureFile2x) {
    fail(`${id}.textureFile2x must be a path`);
  }
  const paddingRaw = shell.padding;
  if (typeof paddingRaw !== 'object' || paddingRaw === null) fail(`${id}.padding must be an object`);
  const padding = paddingRaw as Record<string, unknown>;
  const gridRaw = shell.gridStepPx;
  if (typeof gridRaw !== 'object' || gridRaw === null) fail(`${id}.gridStepPx must be an object`);
  const grid = gridRaw as Record<string, unknown>;
  const poseRaw = shell.pose;
  if (typeof poseRaw !== 'object' || poseRaw === null) fail(`${id}.pose must be an object`);
  const pose = poseRaw as Record<string, unknown>;

  const stats: ShellStats = {
    textureFile,
    textureFile2x,
    texWidth: positive(shell.texWidth, `${id}.texWidth`),
    texHeight: positive(shell.texHeight, `${id}.texHeight`),
    anchorX: nonNegative(shell.anchorX, `${id}.anchorX`),
    anchorY: nonNegative(shell.anchorY, `${id}.anchorY`),
    advanceWidth: positive(shell.advanceWidth, `${id}.advanceWidth`),
    advanceHeight: positive(shell.advanceHeight, `${id}.advanceHeight`),
    padding: {
      top: nonNegative(padding.top, `${id}.padding.top`),
      right: nonNegative(padding.right, `${id}.padding.right`),
      bottom: nonNegative(padding.bottom, `${id}.padding.bottom`),
      left: nonNegative(padding.left, `${id}.padding.left`),
    },
    faceRotationDeg: parseRotation(shell.faceRotationDeg, `${id}.faceRotationDeg`),
    faceQuad: parseQuad(shell.faceQuad, `${id}.faceQuad`),
    faceQuadOrder: typeof shell.faceQuadOrder === 'string' ? shell.faceQuadOrder : '',
    gridStepPx: {
      x: point(grid.x, `${id}.gridStepPx.x`),
      y: point(grid.y, `${id}.gridStepPx.y`),
    },
    projection: typeof shell.projection === 'string' ? shell.projection : '',
    pose: {
      rotateXDeg: finite(pose.rotateXDeg, `${id}.pose.rotateXDeg`),
      rotateYDeg: finite(pose.rotateYDeg, `${id}.pose.rotateYDeg`),
      rotateZDeg: finite(pose.rotateZDeg, `${id}.pose.rotateZDeg`),
    },
  };

  // The manifest's own invariants; a drift here would place every glyph wrong.
  if (
    stats.anchorX + stats.advanceWidth + stats.padding.right !== stats.texWidth ||
    stats.anchorX !== stats.padding.left
  ) {
    fail(`${id} horizontal anchor/advance/padding do not add up to texWidth`);
  }
  if (
    stats.anchorY + stats.advanceHeight + stats.padding.bottom !== stats.texHeight ||
    stats.anchorY !== stats.padding.top
  ) {
    fail(`${id} vertical anchor/advance/padding do not add up to texHeight`);
  }
  const rotation = screenRotationOfQuad(stats.faceQuad);
  if (rotation !== stats.faceRotationDeg) {
    fail(
      `${id} faceQuad first edge is ${rotation}° but faceRotationDeg is ${stats.faceRotationDeg}°`,
    );
  }
  return stats;
}

/** Parse and validate a decoded `shells.json`. */
export function parseShellsManifest(raw: unknown): ShellsManifest {
  if (typeof raw !== 'object' || raw === null) fail('document must be an object');
  const doc = raw as Record<string, unknown>;
  if (doc.version !== 1) fail(`version must be 1, got ${String(doc.version)}`);
  const pixelRatio = positive(doc.pixelRatio, 'pixelRatio');
  if (pixelRatio !== 1 && pixelRatio !== 2) fail('pixelRatio must be 1 or 2');
  if (typeof doc.shells !== 'object' || doc.shells === null) fail('shells must be an object');
  const shellsRaw = doc.shells as Record<string, unknown>;
  const ids = Object.keys(shellsRaw);
  if (ids.length !== SHELL_IDS.length) fail(`expected ${SHELL_IDS.length} shells, got ${ids.length}`);

  const shells = {} as Record<ShellId, ShellStats>;
  for (const id of ids) {
    if (!isShellId(id)) fail(`unknown shell ${id}`);
    shells[id] = parseShell(id, shellsRaw[id]);
  }
  for (const id of SHELL_IDS) {
    if (!shells[id]) fail(`missing shell ${id}`);
  }

  return {
    version: 1,
    generatedBy: typeof doc.generatedBy === 'string' ? doc.generatedBy : '',
    pixelRatio,
    shells,
  };
}
